        /* ==================================================================
         * SECTION 140
         * National Alert Level Calculation
         * ================================================================== */

        calculateNationalAlertLevel(
            horizonAggregation,
            riskScore,
            confidenceScore
        ) {

            if (
                !horizonAggregation ||
                typeof horizonAggregation !==
                    "object" ||
                horizonAggregation.cityCount ===
                    0
            ) {
                return "NONE";
            }

            const risk =
                clampPercentage(
                    riskScore,
                    0
                );

            const confidence =
                clampPercentage(
                    confidenceScore,
                    0
                );

            const extremeCities =
                Math.max(
                    0,
                    toFiniteNumber(
                        horizonAggregation.risk
                            ?.extremeRiskCityCount,
                        0
                    )
                );

            const severeCities =
                Math.max(
                    0,
                    toFiniteNumber(
                        horizonAggregation.risk
                            ?.severeRiskCityCount,
                        0
                    )
                );

            const highRiskCities =
                Math.max(
                    0,
                    toFiniteNumber(
                        horizonAggregation.risk
                            ?.highRiskCityCount,
                        0
                    )
                );

            const confirmedCoverage =
                clampPercentage(
                    horizonAggregation.coverage
                        ?.confirmedCoveragePercentage,
                    0
                );

            const maximumRainfall =
                Math.max(
                    0,
                    toFiniteNumber(
                        horizonAggregation.rainfall
                            ?.maximumRainfallMm,
                        0
                    )
                );

            if (
                (
                    risk >=
                        90 &&
                    confidence >=
                        55
                ) ||
                extremeCities >=
                    2 ||
                (
                    extremeCities >=
                        1 &&
                    maximumRainfall >=
                        40
                )
            ) {
                return "EMERGENCY";
            }

            if (
                (
                    risk >=
                        80 &&
                    confidence >=
                        50
                ) ||
                severeCities >=
                    2 ||
                (
                    severeCities >=
                        1 &&
                    confirmedCoverage >=
                        25
                )
            ) {
                return "CRITICAL";
            }

            if (
                (
                    risk >=
                        65 &&
                    confidence >=
                        45
                ) ||
                highRiskCities >=
                    3 ||
                maximumRainfall >=
                    25
            ) {
                return "WARNING";
            }

            if (
                risk >=
                    45 ||
                highRiskCities >
                    0 ||
                confirmedCoverage >
                    0
            ) {
                return "WATCH";
            }

            if (
                risk >=
                    25
            ) {
                return "ADVISORY";
            }

            return "NONE";
        }

