        /* ==================================================================
         * SECTION 206
         * National Confidence Trajectory
         * ================================================================== */

        buildNationalConfidenceTrajectory(
            nationalAggregation
        ) {

            const confidenceScore =
                this.buildNationalConfidenceScoreTrajectory(
                    nationalAggregation
                );

            const weightedConfidence =
                this.buildNationalWeightedConfidenceTrajectory(
                    nationalAggregation
                );

            const averageConfidence =
                this.buildNationalAverageConfidenceTrajectory(
                    nationalAggregation
                );

            const lowConfidenceCities =
                this.buildNationalLowConfidenceCityTrajectory(
                    nationalAggregation
                );

            const highConfidenceCities =
                this.buildNationalHighConfidenceCityTrajectory(
                    nationalAggregation
                );

            const compositeSlope =

                confidenceScore.slope *
                    0.40 +

                weightedConfidence.slope *
                    0.30 +

                averageConfidence.slope *
                    0.20 +

                highConfidenceCities.slope *
                    3 *
                    0.06 -

                lowConfidenceCities.slope *
                    3 *
                    0.04;

            const direction =
                this.classifyNationalMetricSlopeDirection(

                    compositeSlope,

                    {
                        slightThreshold:
                            0.05,

                        moderateThreshold:
                            0.18,

                        rapidThreshold:
                            0.45
                    }
                );

            const strength =
                clampPercentage(

                    confidenceScore.strength *
                        0.40 +

                    weightedConfidence.strength *
                        0.30 +

                    averageConfidence.strength *
                        0.20 +

                    lowConfidenceCities.strength *
                        0.05 +

                    highConfidenceCities.strength *
                        0.05,

                    0
                );

            return {

                available:
                    confidenceScore.available,

                primary:
                    confidenceScore,

                confidenceScore,

                weightedConfidence,

                averageConfidence,

                lowConfidenceCities,

                highConfidenceCities,

                compositeSlope:
                    roundNumber(
                        compositeSlope,
                        4
                    ),

                direction,

                directionLabel:
                    this.getNationalMetricDirectionLabel(
                        direction
                    ),

                strength:
                    roundNumber(
                        strength,
                        2
                    ),

                generatedAt:
                    this.getNowISO()
            };
        }

