        getNationalIncidentStates() {

            return {

                DETECTED:
                    "DETECTED",

                REPORTED:
                    "REPORTED",

                VALIDATING:
                    "VALIDATING",

                CONFIRMED:
                    "CONFIRMED",

                ASSIGNED:
                    "ASSIGNED",

                RESPONDING:
                    "RESPONDING",

                CONTAINED:
                    "CONTAINED",

                MONITORING:
                    "MONITORING",

                RESOLVED:
                    "RESOLVED",

                CLOSED:
                    "CLOSED",

                DUPLICATE:
                    "DUPLICATE",

                REJECTED:
                    "REJECTED",

                ESCALATED:
                    "ESCALATED",

                REOPENED:
                    "REOPENED"
            };
        }

        normalizeNationalIncidentState(
            state
        ) {

            const normalizedState =
                String(
                    state ??
                    "DETECTED"
                )
                    .trim()
                    .toUpperCase()
                    .replace(
                        /[\s-]+/g,
                        "_"
                    );

            const aliases = {

                NEW:
                    "DETECTED",

                CREATED:
                    "DETECTED",

                SUBMITTED:
                    "REPORTED",

                VERIFYING:
                    "VALIDATING",

                VERIFIED:
                    "CONFIRMED",

                ACTIVE:
                    "RESPONDING",

                IN_PROGRESS:
                    "RESPONDING",

                CONTROLLED:
                    "CONTAINED",

                OBSERVING:
                    "MONITORING",

                COMPLETED:
                    "RESOLVED",

                FINISHED:
                    "CLOSED",

                MERGED:
                    "DUPLICATE",

                INVALID:
                    "REJECTED",

                CRITICAL:
                    "ESCALATED",

                OPENED_AGAIN:
                    "REOPENED"
            };

            const resolvedState =
                aliases[
                    normalizedState
                ] ??
                normalizedState;

            const validStates =
                Object.values(
                    this.getNationalIncidentStates()
                );

            return validStates.includes(
                resolvedState
            )
                ? resolvedState
                : "DETECTED";
        }

