        getNationalIncidentSeverityLevels() {

            return {

                INFORMATIONAL:
                    "INFORMATIONAL",

                LOW:
                    "LOW",

                MODERATE:
                    "MODERATE",

                HIGH:
                    "HIGH",

                CRITICAL:
                    "CRITICAL",

                CATASTROPHIC:
                    "CATASTROPHIC"
            };
        }

        normalizeNationalIncidentSeverity(
            severity
        ) {

            const normalizedSeverity =
                String(
                    severity ??
                    "INFORMATIONAL"
                )
                    .trim()
                    .toUpperCase()
                    .replace(
                        /[\s-]+/g,
                        "_"
                    );

            const aliases = {

                INFO:
                    "INFORMATIONAL",

                MINOR:
                    "LOW",

                MEDIUM:
                    "MODERATE",

                MAJOR:
                    "HIGH",

                SEVERE:
                    "CRITICAL",

                EXTREME:
                    "CATASTROPHIC",

                DISASTER:
                    "CATASTROPHIC"
            };

            const resolvedSeverity =
                aliases[
                    normalizedSeverity
                ] ??
                normalizedSeverity;

            const validLevels =
                Object.values(
                    this.getNationalIncidentSeverityLevels()
                );

            return validLevels.includes(
                resolvedSeverity
            )
                ? resolvedSeverity
                : "INFORMATIONAL";
        }

